import React from 'react';
import { Helicycles } from './index';

const previews = {
  componentName: 'Helicycles',
  importPath: 'components/Helicycles',
  previews: [
    { name: '3D rig', description: "Helicycles: pedal-powered orange helicopter pods with pink rotors (HELICAR).", render: () => <Helicycles /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SKIN_TONES } from '../Guest';

// Helicycles matched to the RCT2 HELICAR sprite: a chubby ORANGE helicopter
// pod with a big open cockpit mouth, PINK twin-blade rotor and tail fin, pedal
// cranks below — puttering around a circle a little way off the ground.
export function Helicycles() {
  return (
    <Stage
      distance={6}
      targetY={0.9}
      build={(t, g) => {
        const ORANGE = 0xd6541a;
        const PINK = 0xd6338c;
        g.add(cyl(t, 2.2, 2.3, 0.1, 0x6f9e54, [0, 0.05, 0], { tex: 'grass', repeat: [8, 8], rough: 1, seg: 32 })); // pad lawn
        const flyers: { grp: THREE.Group; rotor: THREE.Group; ph: number }[] = [];
        for (let i = 0; i < 2; i++) {
          const heli = new t.Group();
          g.add(heli);
          // pod: fat rounded body with open front mouth
          const body = ball(t, 0.42, ORANGE, [0, 0, 0], { tex: 'plastic', repeat: [3, 2], rough: 0.4 });
          body.scale.set(1, 0.85, 1.15);
          heli.add(body);
          heli.add(box(t, [0.5, 0.4, 0.3], 0x241812, [0, 0.02, 0.3], { rough: 0.9 })); // open cockpit mouth
          heli.add(cyl(t, 0.06, 0.09, 0.5, ORANGE, [0, 0.05, -0.55], { tex: 'plastic', rough: 0.4, seg: 10, rotX: Math.PI / 2 })); // tail boom
          heli.add(box(t, [0.04, 0.28, 0.2], PINK, [0, 0.2, -0.8], { rough: 0.5 })); // tail fin
          // rotor
          const rotor = new t.Group();
          rotor.position.y = 0.45;
          heli.add(rotor);
          rotor.add(cyl(t, 0.03, 0.03, 0.12, 0x2c2c30, [0, 0, 0], { metal: 0.5, seg: 8 }));
          [-1, 1].forEach((s) => rotor.add(box(t, [1.0, 0.02, 0.09], PINK, [s * 0.5, 0.05, 0], { rough: 0.5 })));
          // pedal cranks + skids
          heli.add(cyl(t, 0.02, 0.02, 0.24, 0x2c2c30, [0, -0.36, 0.12], { rotZ: Math.PI / 2, metal: 0.5, seg: 6 }));
          [-0.2, 0.2].forEach((x) => heli.add(box(t, [0.06, 0.03, 0.7], 0xc44a14, [x, -0.44, 0], { rough: 0.5 })));
          const p = buildPeep(t, { skin: SKIN_TONES[(i * 2) % SKIN_TONES.length], shirt: i ? 0x2e9e54 : 0x2f6fd0, seated: true });
          p.group.scale.setScalar(0.4);
          p.group.position.set(0, -0.22, 0.16);
          heli.add(p.group);
          flyers.push({ grp: heli, rotor, ph: i * Math.PI });
        }
        return (time) => {
          flyers.forEach(({ grp, rotor, ph }) => {
            const a = time * 0.5 + ph;
            grp.position.set(Math.cos(a) * 1.4, 0.75 + Math.sin(time * 1.3 + ph) * 0.12, Math.sin(a) * 1.4);
            grp.rotation.y = -a; // nose along travel
            grp.rotation.z = 0.08;
            rotor.rotation.y = time * 14;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { PaddleBoats } from './index';

const previews = {
  componentName: 'PaddleBoats',
  importPath: 'components/PaddleBoats',
  previews: [
    { name: '3D rig', description: "Paddle boats: slate hulls with orange planks and churning stern wheels (SPBOAT).", render: () => <PaddleBoats /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SKIN_TONES } from '../Guest';

// Paddle boats matched to the RCT2 SPBOAT sprite: a dark slate-teal hull with
// ORANGE plank stripes across the deck, a churning red paddle wheel at the
// stern and two peeps pedalling around a pond.
export function PaddleBoats() {
  return (
    <Stage
      distance={6}
      targetY={0.4}
      background="#bfe6f2"
      build={(t, g) => {
        const HULL = 0x2e4444; // (sprite #203030/#304040)
        const ORANGE = 0xe8641c;
        // pond
        g.add(cyl(t, 2.5, 2.6, 0.16, 0x9a8a5f, [0, 0.02, 0], { tex: 'sand', repeat: [12, 1], rough: 1, seg: 36 }));
        g.add(cyl(t, 2.4, 2.4, 0.08, 0x2a6f9e, [0, 0.12, 0], { rough: 0.3, emissive: 0x123a55, seg: 36 }));
        const boats: { grp: THREE.Group; wheel: THREE.Group; ph: number }[] = [];
        for (let i = 0; i < 2; i++) {
          const boat = new t.Group();
          g.add(boat);
          // hull with orange plank stripes
          boat.add(box(t, [0.6, 0.16, 1.15], HULL, [0, 0.06, 0], { tex: 'plastic', repeat: [2, 3], rough: 0.5 }));
          for (let k = 0; k < 5; k++) boat.add(box(t, [0.62, 0.03, 0.1], ORANGE, [0, 0.15, -0.4 + k * 0.2], { rough: 0.5 }));
          boat.add(box(t, [0.5, 0.2, 0.25], HULL, [0, 0.22, -0.28], { tex: 'plastic', rough: 0.5 })); // seat block
          // stern paddle wheel
          const wheel = new t.Group();
          wheel.position.set(0, 0.12, -0.62);
          boat.add(wheel);
          for (let k = 0; k < 6; k++) wheel.add(box(t, [0.5, 0.02, 0.12], 0xb03030, [0, 0, 0], { rough: 0.55, rotX: (k / 6) * Math.PI }));
          [-0.26, 0.26].forEach((x) => wheel.add(cyl(t, 0.1, 0.1, 0.03, 0xb03030, [x, 0, 0], { rotZ: Math.PI / 2, rough: 0.55, seg: 12 })));
          // two pedalling peeps
          [0.13, -0.13].forEach((x, pi) => {
            const p = buildPeep(t, { skin: SKIN_TONES[(i + pi * 2) % SKIN_TONES.length], shirt: pi ? 0xe0a020 : 0x18a0a0, seated: true });
            p.group.scale.setScalar(0.34);
            p.group.position.set(x, 0.2, 0.02);
            boat.add(p.group);
          });
          boats.push({ grp: boat, wheel, ph: i * Math.PI });
        }
        return (time) => {
          boats.forEach(({ grp, wheel, ph }) => {
            const a = time * 0.35 + ph;
            grp.position.set(Math.cos(a) * 1.5, 0.1 + Math.sin(time * 2.2 + ph) * 0.015, Math.sin(a) * 1.5);
            grp.rotation.y = -a; // bow along travel
            wheel.rotation.x = time * 4;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { BurgerShop } from './index';

const previews = {
  componentName: 'BurgerShop',
  importPath: 'components/BurgerShop',
  previews: [
    { name: '3D rig', description: "Burger shop: the building IS a giant sesame-bun burger with a serving hatch (BURGB).", render: () => <BurgerShop /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep } from '../Guest';

// Burger shop matched to the RCT2 BURGB stall: the building IS a giant burger
// — sesame-dome top bun, lettuce ruffle, patty and cheese layers, bottom bun —
// with a serving hatch cut into the front, a counter and a queueing guest.
export function BurgerShop() {
  return (
    <Stage
      distance={5}
      targetY={0.8}
      build={(t, g) => {
        const BUN = 0xc9903c;
        const BUN_D = 0xa8722a;
        const LETTUCE = 0x5c9e2e;
        const PATTY = 0x5a3520;
        const CHEESE = 0xe8b020;
        // bottom bun + patty + cheese + lettuce + top bun dome
        g.add(cyl(t, 0.95, 1.05, 0.35, BUN_D, [0, 0.2, 0], { tex: 'sand', repeat: [8, 1], rough: 0.8, seg: 28 }));
        g.add(cyl(t, 1.02, 1.0, 0.18, PATTY, [0, 0.46, 0], { tex: 'asphalt', repeat: [6, 1], rough: 0.95, seg: 28 }));
        g.add(cyl(t, 1.05, 1.02, 0.07, CHEESE, [0, 0.58, 0], { rough: 0.5, seg: 28 }));
        for (let i = 0; i < 14; i++) {
          const a = (i / 14) * Math.PI * 2;
          g.add(ball(t, 0.16, LETTUCE, [Math.cos(a) * 0.98, 0.66, Math.sin(a) * 0.98], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.9 })); // ruffle
        }
        const dome = ball(t, 1.05, BUN, [0, 0.72, 0], { tex: 'sand', repeat: [6, 3], rough: 0.75 });
        dome.scale.set(1, 0.72, 1);
        g.add(dome);
        // sesame seeds
        for (let i = 0; i < 16; i++) {
          const a = (i / 16) * Math.PI * 2 + (i % 2) * 0.2;
          const r = 0.45 + (i % 3) * 0.2;
          const s = ball(t, 0.045, 0xf0e2b8, [Math.cos(a) * r, 0.72 + Math.sqrt(Math.max(0, 1 - (r / 1.05) ** 2)) * 0.72, Math.sin(a) * r], { rough: 0.6 });
          s.scale.set(1, 0.5, 1.4);
          g.add(s);
        }
        // serving hatch + counter + menu board
        g.add(box(t, [0.7, 0.5, 0.2], 0x241812, [0, 0.55, 0.97], { rough: 0.9 }));
        g.add(box(t, [0.8, 0.07, 0.3], 0x8a5a28, [0, 0.34, 1.08], { tex: 'wood', repeat: [3, 1], rough: 0.8 })); // counter
        g.add(box(t, [0.34, 0.26, 0.03], 0xf0e6d0, [0.62, 0.85, 0.85], { rough: 0.6, rotY: -0.4 })); // menu
        // queueing guest
        const p = buildPeep(t, { shirt: 0x2f6fd0, expression: 'happy' });
        p.group.scale.setScalar(0.5);
        p.group.position.set(0.35, 0, 1.5);
        p.group.rotation.y = Math.PI;
        g.add(p.group);
        return (time) => {
          p.group.position.y = Math.abs(Math.sin(time * 2)) * 0.01; // idle shuffle
        };
      }}
    />
  );
}

import React from 'react';
import { HotDogStand } from './index';

const previews = {
  componentName: 'HotDogStand',
  importPath: 'components/HotDogStand',
  previews: [
    { name: '3D rig', description: "Hot dog stand: stone kiosk, striped awning, giant hot dog on the roof (HOTDS).", render: () => <HotDogStand /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep } from '../Guest';

// Hot dog stand matched to the RCT2 HOTDS stall: a little fieldstone kiosk
// with a BLUE/WHITE striped awning roof and a GIANT HOT DOG (bun, sausage,
// mustard squiggle) lying along the ridge. Serving hatch + counter in front.
export function HotDogStand() {
  return (
    <Stage
      distance={4.8}
      targetY={0.8}
      build={(t, g) => {
        const STONE = 0xb6ac98;
        const BLUE = 0x3a6fc0;
        // fieldstone kiosk
        g.add(box(t, [1.5, 1.0, 1.2], STONE, [0, 0.5, 0], { tex: 'concrete', repeat: [6, 4], rough: 0.95, bump: 0.04 }));
        // pitched striped awning roof
        for (let i = 0; i < 8; i++) {
          const col = i % 2 ? 0xffffff : BLUE;
          g.add(box(t, [0.22, 0.05, 0.85], col, [-0.77 + i * 0.22, 1.22, 0.34], { rough: 0.6, rotX: -0.5 }));
          g.add(box(t, [0.22, 0.05, 0.85], col, [-0.77 + i * 0.22, 1.22, -0.34], { rough: 0.6, rotX: 0.5 }));
        }
        g.add(box(t, [1.7, 0.06, 0.12], BLUE, [0, 1.42, 0], { rough: 0.6 })); // ridge cap
        // scalloped awning skirt over the hatch
        for (let i = 0; i < 6; i++) g.add(ball(t, 0.09, i % 2 ? 0xffffff : BLUE, [-0.6 + i * 0.24, 0.98, 0.64], { flat: true, rough: 0.6 }));
        // GIANT hot dog on the ridge: bun halves + sausage + mustard beads
        [-1, 1].forEach((s) => {
          const bun = cyl(t, 0.16, 0.2, 1.5, 0xd9a04c, [0, 1.52, s * 0.12], { tex: 'sand', repeat: [6, 1], rough: 0.8, seg: 12, rotZ: Math.PI / 2 });
          g.add(bun);
        });
        g.add(cyl(t, 0.13, 0.13, 1.7, 0xa03a20, [0, 1.62, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.55, seg: 12, rotZ: Math.PI / 2 })); // sausage
        for (let i = 0; i < 7; i++) g.add(ball(t, 0.05, 0xe8c020, [-0.66 + i * 0.22, 1.72, (i % 2 ? 1 : -1) * 0.04], { rough: 0.5 })); // mustard squiggle
        // hatch + counter + queue guest
        g.add(box(t, [0.6, 0.45, 0.1], 0x241812, [0, 0.62, 0.62], { rough: 0.9 }));
        g.add(box(t, [0.75, 0.07, 0.26], 0x8a5a28, [0, 0.42, 0.72], { tex: 'wood', repeat: [3, 1], rough: 0.8 }));
        const p = buildPeep(t, { shirt: 0xe0a020, expression: 'neutral' });
        p.group.scale.setScalar(0.5);
        p.group.position.set(-0.3, 0, 1.15);
        p.group.rotation.y = Math.PI;
        g.add(p.group);
        return () => undefined;
      }}
    />
  );
}

import React from 'react';
import { SodaStand } from './index';

const previews = {
  componentName: 'SodaStand',
  importPath: 'components/SodaStand',
  previews: [
    { name: '3D rig', description: "Soda stand: a cluster of giant soda cans with ring pulls and a straw (DRNKS).", render: () => <SodaStand /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// Soda stand matched to the RCT2 DRNKS stall: a cluster of GIANT SODA CANS —
// red and green with label bands and ring-pulls on top — one can carrying the
// serving hatch and counter, plus a bendy straw.
export function SodaStand() {
  return (
    <Stage
      distance={4.8}
      targetY={0.8}
      build={(t, g) => {
        const cans: [number, number, number, number, number][] = [
          // x, z, radius, height, colour
          [0, 0.15, 0.55, 1.5, 0xc42a2a],
          [-0.62, -0.35, 0.4, 1.15, 0x2e8e3a],
          [0.6, -0.35, 0.38, 1.05, 0x2e8e3a],
          [0.05, -0.75, 0.3, 0.85, 0xc42a2a],
        ];
        cans.forEach(([x, z, r, h, col], ci) => {
          g.add(cyl(t, r, r, h, col, [x, h / 2, z], { tex: 'plastic', repeat: [6, 2], rough: 0.4, seg: 22 }));
          // label band + brand stripe
          g.add(cyl(t, r + 0.015, r + 0.015, h * 0.34, 0xf0f0f0, [x, h * 0.55, z], { rough: 0.45, seg: 22 }));
          g.add(cyl(t, r + 0.02, r + 0.02, 0.05, col === 0xc42a2a ? 0x8a1a1a : 0x1a5e24, [x, h * 0.55, z], { rough: 0.45, seg: 22 }));
          // silver lid + ring pull
          g.add(cyl(t, r * 0.94, r, 0.06, 0xd0d4da, [x, h + 0.02, z], { tex: 'metal', metal: 0.8, rough: 0.25, seg: 22 }));
          const pull = new t.Mesh(new t.TorusGeometry(r * 0.2, 0.025, 8, 14), new t.MeshStandardMaterial({ color: 0xc9ccd2, metalness: 0.8, roughness: 0.25 }));
          pull.rotation.x = -Math.PI / 2;
          pull.position.set(x + r * 0.2, h + 0.07, z);
          g.add(pull);
          g.add(box(t, [r * 0.36, 0.02, r * 0.14], 0xb9bec6, [x, h + 0.05, z], { metal: 0.8, rough: 0.25, rotY: ci }));
        });
        // bendy straw out of the big can
        g.add(cyl(t, 0.045, 0.045, 0.6, 0xf0f0f0, [0.22, 1.75, 0.1], { rough: 0.5, seg: 10 }));
        g.add(cyl(t, 0.045, 0.045, 0.3, 0xc42a2a, [0.36, 2.08, 0.1], { rough: 0.5, seg: 10, rotZ: -0.8 }));
        // hatch + counter in the big red can + queue guest
        g.add(box(t, [0.5, 0.42, 0.12], 0x241812, [0, 0.62, 0.66], { rough: 0.9 }));
        g.add(box(t, [0.66, 0.06, 0.24], 0x8a5a28, [0, 0.42, 0.76], { tex: 'wood', repeat: [3, 1], rough: 0.8 }));
        const p = buildPeep(t, { shirt: 0x18a0a0, expression: 'happy' });
        p.group.scale.setScalar(0.5);
        p.group.position.set(0.4, 0, 1.2);
        p.group.rotation.y = Math.PI;
        g.add(p.group);
        return () => undefined;
      }}
    />
  );
}

import React from 'react';
import { CottonCandyStand } from './index';

const previews = {
  componentName: 'CottonCandyStand',
  importPath: 'components/CottonCandyStand',
  previews: [
    { name: '3D rig', description: "Cotton candy stand: a giant fluffy pink floss cloud with a hatch (CNDYF).", render: () => <CottonCandyStand /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep } from '../Guest';

// Cotton candy stand matched to the RCT2 CNDYF stall: the building is a GIANT
// fluffy pink-white candy-floss cloud on a stick stump, with a serving hatch
// tucked into the fluff, a counter, and display cones of floss beside it.
export function CottonCandyStand() {
  return (
    <Stage
      distance={4.8}
      targetY={0.9}
      build={(t, g) => {
        const PINKS = [0xf2c4d4, 0xf7d7e2, 0xecb0c8, 0xfae6ee];
        // stick stump + main cloud of overlapping fluff balls
        g.add(cyl(t, 0.18, 0.22, 0.5, 0xe8e2d2, [0, 0.25, 0], { rough: 0.7, seg: 12 }));
        const blobs: [number, number, number, number][] = [
          [0, 1.05, 0, 0.85],
          [-0.55, 0.85, 0.25, 0.5],
          [0.55, 0.9, -0.2, 0.55],
          [0.15, 1.55, 0.1, 0.55],
          [-0.35, 1.4, -0.35, 0.45],
          [0.4, 1.35, 0.4, 0.42],
          [-0.15, 0.75, 0.55, 0.42],
        ];
        blobs.forEach(([x, y, z, r], i) => g.add(ball(t, r, PINKS[i % PINKS.length], [x, y, z], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.95 })));
        // wispy strands
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          g.add(cyl(t, 0.015, 0.03, 0.3, 0xf7d7e2, [Math.cos(a) * 0.95, 1.0 + (i % 3) * 0.3, Math.sin(a) * 0.95], { rough: 0.95, seg: 6, rotZ: Math.cos(a), rotX: Math.sin(a) }));
        }
        // serving hatch nestled in the fluff + counter
        g.add(box(t, [0.55, 0.45, 0.2], 0x3a2030, [0, 0.75, 0.78], { rough: 0.9 }));
        g.add(box(t, [0.7, 0.06, 0.26], 0xd88ab0, [0, 0.52, 0.9], { tex: 'plastic', repeat: [3, 1], rough: 0.6 }));
        // display floss cones on the counter
        [-0.2, 0.2].forEach((x, i) => {
          g.add(cyl(t, 0.015, 0.04, 0.22, 0xf0e6d0, [x, 0.66, 0.92], { rough: 0.7, seg: 8 }));
          g.add(ball(t, 0.09, PINKS[i * 2], [x, 0.82, 0.92], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.95 }));
        });
        // queue guest holding a floss
        const p = buildPeep(t, { shirt: 0x8e44ad, expression: 'happy' });
        p.group.scale.setScalar(0.5);
        p.group.position.set(0.45, 0, 1.35);
        p.group.rotation.y = Math.PI;
        g.add(p.group);
        const held = new t.Group();
        held.position.set(0.32, 0.45, 1.3);
        g.add(held);
        held.add(cyl(t, 0.012, 0.03, 0.18, 0xf0e6d0, [0, 0, 0], { rough: 0.7, seg: 8 }));
        held.add(ball(t, 0.07, 0xecb0c8, [0, 0.13, 0], { tex: 'leaf', repeat: [2, 2], flat: true, rough: 0.95 }));
        return (time) => {
          held.rotation.z = Math.sin(time * 2) * 0.1;
        };
      }}
    />
  );
}
